1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eceef1;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    padding: 16px;
22	    background: #1f2328;
23	    border-radius: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    height: 88px;
28	    padding: 0 12px;
29	    margin-bottom: 16px;
30	    display: flex;
31	    align-items: flex-end;
32	    justify-content: flex-end;
33	    color: #fff;
34	    font-size: 48px;
35	    font-weight: 300;
36	    white-space: nowrap;
37	    overflow: hidden;
38	    font-variant-numeric: tabular-nums;
39	  }
40	  .display.small { font-size: 32px; }
41	  .display.tiny { font-size: 22px; }
42	  .keys {
43	    display: grid;
44	    grid-template-columns: repeat(4, 1fr);
45	    gap: 10px;
46	  }
47	  button {
48	    height: 64px;
49	    border: 0;
50	    border-radius: 14px;
51	    font: inherit;
52	    font-size: 24px;
53	    color: #fff;
54	    background: #3a4048;
55	    cursor: pointer;
56	    user-select: none;
57	  }
58	  button:hover { filter: brightness(1.12); }
59	  button:active { filter: brightness(0.9); }
60	  button:focus-visible { outline: 2px solid #8ab4f8; outline-offset: 2px; }
61	  .op { background: #f59e0b; }
62	  .op.active { background: #fff; color: #f59e0b; }
63	  .fn { background: #9aa0a6; color: #111; }
64	  .wide { grid-column: span 2; }
65	</style>
66	</head>
67	<body>
68	<div class="calc">
69	  <div class="display" data-testid="calc-display" data-value="0" role="status" aria-live="polite">0</div>
70	  <div class="keys">
71	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
72	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
73	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
74	
75	    <button data-testid="key-7" data-digit="7">7</button>
76	    <button data-testid="key-8" data-digit="8">8</button>
77	    <button data-testid="key-9" data-digit="9">9</button>
78	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
79	
80	    <button data-testid="key-4" data-digit="4">4</button>
81	    <button data-testid="key-5" data-digit="5">5</button>
82	    <button data-testid="key-6" data-digit="6">6</button>
83	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
84	
85	    <button data-testid="key-1" data-digit="1">1</button>
86	    <button data-testid="key-2" data-digit="2">2</button>
87	    <button data-testid="key-3" data-digit="3">3</button>
88	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
89	
90	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
91	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
92	  </div>
93	</div>
94	<script>
95	(function () {
96	  var display = document.querySelector('[data-testid="calc-display"]');
97	  var opButtons = document.querySelectorAll('[data-op]');
98	
99	  var state;
100	
101	  function reset() {
102	    state = {
103	      entry: '0',        // text of the number being shown / typed
104	      stored: null,      // left operand
105	      op: null,          // pending operator
106	      typing: false,     // true while the user is building an entry
107	      lastOp: null,      // for repeated equals
108	      lastOperand: null,
109	      error: false
110	    };
111	  }
112	
113	  // Trim floating-point noise such as 0.1 + 0.2 = 0.30000000000000004.
114	  function clean(n) {
115	    if (!isFinite(n)) return n;
116	    return parseFloat(n.toPrecision(15));
117	  }
118	
119	  function compute(a, op, b) {
120	    switch (op) {
121	      case '+': return clean(a + b);
122	      case '-': return clean(a - b);
123	      case '*': return clean(a * b);
124	      case '/': return b === 0 ? NaN : clean(a / b);
125	    }
126	    return b;
127	  }
128	
129	  function currentValue() {
130	    return parseFloat(state.entry);
131	  }
132	
133	  function render() {
134	    var text, value;
135	    if (state.error) {
136	      text = 'Error';
137	      value = 'NaN';
138	    } else {
139	      text = state.entry;
140	      value = String(currentValue());
141	    }
142	    display.textContent = text;
143	    display.setAttribute('data-value', value);
144	    display.classList.toggle('small', text.length > 9 && text.length <= 13);
145	    display.classList.toggle('tiny', text.length > 13);
146	    for (var i = 0; i < opButtons.length; i++) {
147	      var b = opButtons[i];
148	      b.classList.toggle('active', !state.typing && state.op === b.getAttribute('data-op'));
149	    }
150	  }
151	
152	  function setResult(n) {
153	    if (!isFinite(n)) {
154	      reset();
155	      state.error = true;
156	    } else {
157	      state.entry = String(n);
158	    }
159	  }
160	
161	  function inputDigit(d) {
162	    if (state.error) reset();
163	    if (!state.typing) {
164	      state.entry = d;
165	      state.typing = true;
166	      if (state.op === null) state.lastOp = null;
167	    } else if (state.entry === '0') {
168	      state.entry = d;
169	    } else if (state.entry.replace(/[-.]/g, '').length < 16) {
170	      state.entry += d;
171	    }
172	  }
173	
174	  function inputDot() {
175	    if (state.error) reset();
176	    if (!state.typing) {
177	      state.entry = '0.';
178	      state.typing = true;
179	      if (state.op === null) state.lastOp = null;
180	    } else if (state.entry.indexOf('.') === -1) {
181	      state.entry += '.';
182	    }
183	  }
184	
185	  function inputOp(op) {
186	    if (state.error) return;
187	    if (state.op !== null && state.typing) {
188	      setResult(compute(state.stored, state.op, currentValue()));
189	      if (state.error) return;
190	    }
191	    state.stored = currentValue();
192	    state.op = op;
193	    state.typing = false;
194	    state.lastOp = null;
195	  }
196	
197	  function equals() {
198	    if (state.error) return;
199	    if (state.op !== null) {
200	      var b = state.typing ? currentValue() : state.stored;
201	      state.lastOp = state.op;
202	      state.lastOperand = b;
203	      setResult(compute(state.stored, state.op, b));
204	    } else if (state.lastOp !== null) {
205	      setResult(compute(currentValue(), state.lastOp, state.lastOperand));
206	    }
207	    if (state.error) return;
208	    state.op = null;
209	    state.stored = null;
210	    state.typing = false;
211	  }
212	
213	  function handle(el) {
214	    var digit = el.getAttribute('data-digit');
215	    var op = el.getAttribute('data-op');
216	    var action = el.getAttribute('data-action');
217	    if (digit !== null) inputDigit(digit);
218	    else if (op !== null) inputOp(op);
219	    else if (action === 'dot') inputDot();
220	    else if (action === 'equals') equals();
221	    else if (action === 'clear') reset();
222	    render();
223	  }
224	
225	  document.querySelector('.keys').addEventListener('click', function (e) {
226	    var el = e.target.closest('button');
227	    if (el) handle(el);
228	  });
229	
230	  var keyMap = {
231	    '+': 'key-add', '-': 'key-sub', '*': 'key-mul', 'x': 'key-mul', '/': 'key-div',
232	    '.': 'key-dot', ',': 'key-dot', '=': 'key-equals', 'Enter': 'key-equals',
233	    'Escape': 'key-clear', 'c': 'key-clear', 'C': 'key-clear', 'Delete': 'key-clear'
234	  };
235	  document.addEventListener('keydown', function (e) {
236	    if (e.ctrlKey || e.metaKey || e.altKey) return;
237	    var id = /^[0-9]$/.test(e.key) ? 'key-' + e.key : keyMap[e.key];
238	    if (!id) return;
239	    e.preventDefault();
240	    handle(document.querySelector('[data-testid="' + id + '"]'));
241	  });
242	
243	  reset();
244	  render();
245	})();
246	</script>
247	</body>
248	</html>
